dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": "kp phenotypes"
    },
    {
      "parameter": "region",
      "label": "Region by Gene (+-100K) ",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 200000
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "African American",
          "value": "AA"
        },
        {
          "label": "East Asian",
          "value": "EA"
        },
        {
          "label": "Hispanic",
          "value": "HS"
        },
        {
          "label": "South Asian",
          "value": "SA"
        },
        {
          "label": "Europian",
          "value": "EU"
        }
      ]
    },
    {
      "parameter": "csid",
      "label": "Credible Sets ID",
      "type": "input"
    },
    {
      "parameter": "annotation",
      "label": "Annotation",
      "type": "input"
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "ancestry-associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "table format": {
        "initial sort by": {
          "field": "P-Value",
          "direction": "desc"
        },
        "group by": [
          "PhenotypeAncestry"
        ],
        "compare data": {
          "key field": "Variant ID",
          "fields to compare": [
            "PhenotypeAncestry",
            "-log10(P-Value)",
            "P-Value",
            "Beta",
            "MAF",
            "Standard Error",
            "Z Score"
          ]
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "PhenotypeAncestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": "_"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "PhenotypeAncestry",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard Error",
          "Z Score",
          "Consequence"
        ],
        "star column": "Variant ID",
        "tool tips": {
          "Variant ID": "chromosome:position (hg19)_ref/alt",
          "rsID": "Variant ID from dbGaP",
          "Ref/Alt": "Reference allele/alternate allele",
          "P-Value": "Significance of association with the selected phenotype(s)",
          "Beta": "Effect size",
          "MAF": "Minor allele frequency",
          "Z Score": "Beta / Standard error",
          "Consequence": "Impact of the variant for overlapping genes or transcripts, as predicted by the Ensembl Variant Effect Predictor (VEP)",
          "Credible Set": "Posterior Probability of Association for the variant in the selected credible set(s)"
        },
        "locus field": "Locus",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "LDS",
          "label": "LD score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "filter width": "sm",
      "visualizer": {
        "type": "region plot",
        "x axis field": "Position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
    {
      "section id": "credibleSets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Set Credible Set ID",
            "raw field": "credibleSetId"
          }
        ],
        "top rows": [
          "Credible Set ID",
          "PMID",
          "Dataset",
          "Method",
          "Set Credible Set ID"
        ],
        "column formatting": {
          "Set Credible Set ID": {
            "type": [
              "set parameter"
            ],
            "parameter": "csid",
            "target sections": [
              "credibleVariants"
            ]
          }
        }
      }
    },
    {
      "section id": "credibleVariants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "csid"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "table format": {
        "initial sort by": {
          "field": "Position",
          "type": "number",
          "direction": "asc"
        },
        "sections filters": {
          "target sections": [
            {
              "section": "associations",
              "filter by": {
                "filter field": "Variant ID",
                "target field": "Variant ID",
                "type": "search",
                "add to table": {
                  "level": ""
                }
              }
            }
          ]
        },
        "group by": [
          "Credible Set ID"
        ],
        "data convert": [
          {
            "type": "raw",
            "field name": "Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Odds Ratio",
            "raw field": "oddsRatio"
          },
          {
            "type": "raw",
            "field name": "PPA",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "Sample",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "Position",
          "Ancestry",
          "Credible Set ID",
          "PPA",
          "P-Value",
          "Beta",
          "Odds Ratio",
          "EAF",
          "MAF",
          "Z Score",
          "Standard Error",
          "Sample"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "PPA": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          }
        }
      }
    },
    {
      "section id": "globalEnrichment",
      "header": "Global Enrichment",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "global-enrichment",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Tissue Annotation",
            "fields to join": [
              "tissue",
              "annotation"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "PheAnceAnnoTiss",
            "fields to join": [
              "phenotype",
              "ancestry",
              "annotation",
              "tissue"
            ],
            "join by": [
              "_",
              "_",
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "Phenotype Ancestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Expected SNPs",
            "raw field": "expectedSNPs"
          },
          {
            "type": "raw",
            "field name": "SNPs",
            "raw field": "SNPs"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "calculate",
            "field name": "Fold",
            "expression": [
              "SNPs",
              "/",
              "expectedSNPs"
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "Test",
            "expression": [
              "(",
              "SNPs",
              "/",
              "expectedSNPs",
              ")",
              "*",
              "pValue"
            ],
            "calculation type": "math"
          }
        ],
        "top rows": [
          "Tissue",
          "Annotation",
          "Phenotype Ancestry",
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold",
          "Set Annotation",
          "Set Tissue"
        ],
        "column formatting": {
