            "type": [
              "scientific notation"
            ]
          },
          "Expected SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold": {
            "type": [
              "scientific notation"
            ]
          },
          "Set Annotation": {
            "type": [
              "set parameter"
            ],
            "parameter": "annotation",
            "target sections": [
