        ],
        "compare data": {
          "key field": "Tissue Annotation",
          "fields to compare": [
            "Phenotype Ancestry",
            "P-Value",
            "Expected SNPs",
            "SNPs",
            "Fold"
          ]
        }
      },
      "visualizer": {
        "type": "scatter plot",
        "render type": "single plot",
        "group by": "Phenotype Ancestry",
        "color by": "Annotation",
        "y axis field": "Fold",
        "y axis label": "Fold (SNPs/expectedSNPs)",
        "x axis field": "P-Value(-log10)",
        "x axis label": "-Log10(p-value)",
        "ticks decimal point": "2",
        "render by": "PheAnceAnnoTiss",
        "hover content": [
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold"
        ],
        "height": 120,
        "width": 200,
        "plot margin": {
          "left": 60,
          "right": 20,
          "top": 40,
          "bottom": 50,
          "bump": 5
        }
      },
      "filters": [
        {
          "field": "Ancestry",
          "label": "Ancestry",
          "type": "checkbox"
        },
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        }
      ]
    },
    {
      "section id": "tissueRegions",
      "header": "Tissue Regions",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "tissue-regions",
        "parameters": [
          "tissue",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "filters": [
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox"
        },
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox"
        }
      ],
      "table format": {
        "initial sort by": {
          "field": "Start",
          "type": "number",
          "direction": "asc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Start",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "join",
            "field name": "Region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": ","
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "State",
            "raw field": "state"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "join",
            "field name": "AnnotationTissue",
            "fields to join": [
              "annotation",
              "tissue"
            ],
            "join by": "_"
          }
        ],
        "top rows": [
          "Biosample",
          "Region",
          "Dataset",
          "State",
          "Method",
          "Source",
          "Tissue",
          "Annotation",
          "AnnotationTissue"
        ]
      }
    }
  ]
